using UnityEngine;

// 1. Declara heredando de ScriptableObject
[CreateAssetMenu(fileName = "WeaponData", menuName = "Game/Weapon Data")]
public class WeaponData : ScriptableObject
{
    public string weaponName;
    public int damage;
    public float attackSpeed;
    public Sprite icon;
}

// Crear en Unity: clic derecho en Project → Game → Weapon Data
// Aparece un archivo WeaponData.asset en tu carpeta

public class Warrior : MonoBehaviour
{
    // Arrastra el .asset desde el Inspector
    [SerializeField] private WeaponData weaponData;

    void Attack(IDamageable target)
    {
        // Lee los datos del SO
        target.TakeDamage(weaponData.damage);
        Debug.Log($"Atacando con {weaponData.weaponName}");
    }
}
// Múltiples Warriors pueden referenciar el MISMO WeaponData.asset
// Cambiar el .asset afecta a TODOS los que lo usan

