[CreateAssetMenu(fileName = "EnemyStats", menuName = "Game/Enemy Stats")]
public class EnemyStats : ScriptableObject
{
    public string enemyName;
    public int maxHealth;
    public float moveSpeed;
    public int attackDamage;
}

public class Enemy : MonoBehaviour
{
    [SerializeField] private EnemyStats stats;
    private int currentHealth;

    void Awake()
    {
        currentHealth = stats.maxHealth;
    }
}

[CreateAssetMenu(menuName = "Game/Item")]
public class ItemData : ScriptableObject
{
    public string itemName;
    public Sprite icon;
    public int value;
}

public class InventorySlot : MonoBehaviour
{
    public ItemData item;  // puede ser null si el slot está vacío
    private Image iconImage;

    void Start()
    {
        iconImage = GetComponent<Image>();
        if (item != null)
            iconImage.sprite = item.icon;
    }
}

// Enfoque A: datos hardcoded
public class Sword : MonoBehaviour
{
    private int damage = 35;
    private float speed = 1.2f;
    private string name = "Iron Sword";
}

// Enfoque B: con ScriptableObject
public class Sword : MonoBehaviour
{
    [SerializeField] private WeaponData data;
    // damage, speed y name vienen del .asset
}

[CreateAssetMenu(menuName = "Events/Game Event")]
public class GameEvent : ScriptableObject
{
    private List<GameEventListener> listeners = new List<GameEventListener>();

    public void Raise()
    {
        for (int i = listeners.Count - 1; i >= 0; i--)
            listeners[i].OnEventRaised();
    }

    public void RegisterListener(GameEventListener l) => listeners.Add(l);
    public void UnregisterListener(GameEventListener l) => listeners.Remove(l);
}

public class QuestManager : MonoBehaviour
{
    [SerializeField] private QuestData currentQuest;

    void Start()
    {
        Debug.Log("Quest activa: " + currentQuest.questName);
        Debug.Log("Objetivo: " + currentQuest.objective);
    }
}

